using System;using System.IO;using System.Linq;using System.Text;using System.Numerics;using System.Collections.Generic;using System.Runtime.Serialization;using System.ComponentModel;using System.Globalization;
namespace CircuitoStudio {
[DataContract]public enum ExtremeSourceKind{[EnumMember]Unknown,[EnumMember]NetworkEquivalent,[EnumMember]RotatingInitial}
[DataContract]public sealed class ExtremeSource {
[DataMember,DisplayName("Identificador da fonte")]public string Id{get;set;}[DataMember,DisplayName("ID do quadro de ligação")]public string BoardId{get;set;}[DataMember,DisplayName("Tipo de equivalente inicial")]public ExtremeSourceKind Kind{get;set;}[DataMember,DisplayName("Fonte ativa neste cenário")]public bool? Active{get;set;}[DataMember,DisplayName("R sequência positiva (Ω)")]public double? R1Ohm{get;set;}[DataMember,DisplayName("X sequência positiva (Ω)")]public double? X1Ohm{get;set;}[DataMember,DisplayName("R sequência negativa (Ω)")]public double? R2Ohm{get;set;}[DataMember,DisplayName("X sequência negativa (Ω)")]public double? X2Ohm{get;set;}[DataMember,DisplayName("Referência dos dados")]public string Reference{get;set;}[DataMember,DisplayName("Versão dos dados")]public string DataVersion{get;set;}[DataMember,DisplayName("Condições / correções incluídas")]public string Conditions{get;set;}
public ExtremeSource(){Id=BoardId=Reference=DataVersion=Conditions="";}public ExtremeSource Copy(){return (ExtremeSource)MemberwiseClone();}public void Validate(){if(!Enum.IsDefined(typeof(ExtremeSourceKind),Kind))throw new InvalidDataException("Tipo de fonte de extremos desconhecido.");foreach(var v in new[]{R1Ohm,X1Ohm,R2Ohm,X2Ohm})if(v.HasValue)Project.Range(v.Value,0,1e12,"impedância de sequência da fonte");foreach(var s in new[]{Id,BoardId,Reference,DataVersion,Conditions})ReturnSizing.Text(s,false);}
}
[DataContract]public sealed class ExtremeBranch {
[DataMember,DisplayName("ID do circuito")]public string CircuitId{get;set;}[DataMember,Browsable(false)]public string CircuitContext{get;set;}[DataMember,DisplayName("R sequência positiva (Ω)")]public double? R1Ohm{get;set;}[DataMember,DisplayName("X sequência positiva (Ω)")]public double? X1Ohm{get;set;}[DataMember,DisplayName("R sequência negativa (Ω)")]public double? R2Ohm{get;set;}[DataMember,DisplayName("X sequência negativa (Ω)")]public double? X2Ohm{get;set;}[DataMember,DisplayName("Temperatura do condutor (°C)")]public double? ConductorTemperatureC{get;set;}[DataMember,DisplayName("Referência dos dados")]public string Reference{get;set;}[DataMember,DisplayName("Versão dos dados")]public string DataVersion{get;set;}[DataMember,DisplayName("Condições / correções incluídas")]public string Conditions{get;set;}
public ExtremeBranch(){CircuitId=CircuitContext=Reference=DataVersion=Conditions="";}public ExtremeBranch Copy(){return (ExtremeBranch)MemberwiseClone();}public void Validate(){foreach(var v in new[]{R1Ohm,X1Ohm,R2Ohm,X2Ohm})if(v.HasValue)Project.Range(v.Value,0,1e12,"impedância de sequência do ramo");if(ConductorTemperatureC.HasValue)Project.Range(ConductorTemperatureC.Value,-100,1000,"temperatura de cálculo do ramo");foreach(var s in new[]{CircuitId,CircuitContext,Reference,DataVersion,Conditions})ReturnSizing.Text(s,false);}
}
[DataContract]public sealed class ExtremeCase {
[DataMember,DisplayName("Fator de tensão interna c")]public double VoltageFactor{get;set;}[DataMember,DisplayName("Referência do cenário")]public string Reference{get;set;}[DataMember,DisplayName("Edição / versão dos dados")]public string DataVersion{get;set;}[DataMember,DisplayName("Condições / abrangência")]public string Conditions{get;set;}[DataMember,Browsable(false)]public List<ExtremeSource> Sources{get;set;}[DataMember,Browsable(false)]public List<ExtremeBranch> Branches{get;set;}
public ExtremeCase(){VoltageFactor=1;Reference=DataVersion=Conditions="";Sources=new List<ExtremeSource>();Branches=new List<ExtremeBranch>();}public ExtremeCase Copy(){return new ExtremeCase{VoltageFactor=VoltageFactor,Reference=Reference,DataVersion=DataVersion,Conditions=Conditions,Sources=Sources.Select(s=>s.Copy()).ToList(),Branches=Branches.Select(b=>b.Copy()).ToList()};}public void Validate(){Project.Range(VoltageFactor,.1,2,"fator de tensão do cenário");foreach(var s in new[]{Reference,DataVersion,Conditions})ReturnSizing.Text(s,false);if(Sources==null||Branches==null||Sources.Count>100||Branches.Count>200||Sources.Any(s=>s==null)||Branches.Any(b=>b==null))throw new InvalidDataException("Tabelas de extremos ausentes/excessivas.");foreach(var s in Sources)s.Validate();foreach(var b in Branches)b.Validate();if(Sources.Select(s=>s.Id).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=Sources.Count||Branches.Select(b=>b.CircuitId).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=Branches.Count)throw new InvalidDataException("IDs duplicados nas tabelas de extremos.");}
}
[DataContract]public sealed class FaultExtremeProfile {
[DataMember,Browsable(false)]public string Engine{get;set;}[DataMember,DisplayName("Tensão entre fases de estudo (V)")]public double LineVoltageV{get;set;}[DataMember,DisplayName("Frequência dos dados (Hz)")]public double FrequencyHz{get;set;}[DataMember,DisplayName("Documento de cobertura dos limites")]public string BoundsReference{get;set;}[DataMember,DisplayName("Estados admissíveis / exclusões")]public string Coverage{get;set;}[DataMember,Browsable(false)]public ExtremeCase Minimum{get;set;}[DataMember,Browsable(false)]public ExtremeCase Maximum{get;set;}
public FaultExtremeProfile(){Engine=FaultExtremes.EngineId;BoundsReference=Coverage="";Minimum=new ExtremeCase();Maximum=new ExtremeCase();}public FaultExtremeProfile Copy(){return new FaultExtremeProfile{Engine=Engine,LineVoltageV=LineVoltageV,FrequencyHz=FrequencyHz,BoundsReference=BoundsReference,Coverage=Coverage,Minimum=Minimum.Copy(),Maximum=Maximum.Copy()};}public void Validate(){if(Engine!=FaultExtremes.EngineId)throw new InvalidDataException("Motor de extremos desconhecido.");Project.Range(LineVoltageV,1,1e6,"tensão de extremos");Project.Range(FrequencyHz,1,1000,"frequência de extremos");ReturnSizing.Text(BoundsReference,false);ReturnSizing.Text(Coverage,false);if(Minimum==null||Maximum==null)throw new InvalidDataException("Dois cenários são obrigatórios.");Minimum.Validate();Maximum.Validate();}
}
public sealed class ExtremeContribution{public string SourceId;public Complex[] Current;}
public sealed class ExtremeFaultPoint{public string CircuitId,Location,Fault,Scenario;public double CurrentA;public Complex[] FaultCurrent;public List<ExtremeContribution> Contributions=new List<ExtremeContribution>();public Complex Z1Thevenin,Z2Thevenin;public double ResidualA;}
public sealed class FaultExtremeResult{public bool Accepted;public string Status,Detail;public List<ExtremeFaultPoint> Points=new List<ExtremeFaultPoint>();}
public static class FaultExtremes {
public const string EngineId="cs-extremos-sequencias-v1";public const string SourceHeader="Id;BoardId;Kind;Active;R1Ohm;X1Ohm;R2Ohm;X2Ohm;Reference;DataVersion;Conditions";public const string BranchHeader="CircuitId;CircuitContext;R1Ohm;X1Ohm;R2Ohm;X2Ohm;ConductorTemperatureC;Reference;DataVersion;Conditions";
sealed class Input:Exception{public Input(string s):base(s){}}static void Need(bool ok,string s){if(!ok)throw new Input(s);}static bool Trace(string s){return !String.IsNullOrWhiteSpace(s)&&!s.TrimStart().StartsWith("PREENCHER",StringComparison.OrdinalIgnoreCase);}static Complex Z(double? r,double? x,string label){Need(r.HasValue&&x.HasValue,"R/X desconhecidos: "+label);var z=new Complex(r.Value,x.Value);Need(z.Magnitude>1e-12,"Impedância nula/quase nula não suportada: "+label);return z;}static string N(double d){return d.ToString("R",CultureInfo.InvariantCulture);}public static string Context(Project p,Circuit c){var b=p.Boards.First(x=>x.Circuits.Contains(c));return String.Join("|",new[]{c.Id,b.Id,c.ChildBoardId,c.Phases.ToString(),N(c.Voltage),N(c.LengthM),N(c.CableMm2),N(c.Cable.Parallel),c.Cable.Material.ToString(),N(c.Cable.ResistanceOhmKm),N(c.Cable.ReactanceOhmKm),c.Cable.Reference??"",N(b.Voltage),N(p.Frequency)});}
public static List<ExtremeSource> ImportSources(string path){return ComponentCsv.Import<ExtremeSource>(path,SourceHeader,s=>s.Validate(),s=>s.Id);}public static List<ExtremeBranch> ImportBranches(string path){return ComponentCsv.Import<ExtremeBranch>(path,BranchHeader,b=>b.Validate(),b=>b.CircuitId);}public static void ExportSources(IEnumerable<ExtremeSource> rows,string path){ComponentCsv.Export(rows,path,SourceHeader,s=>s.Validate(),s=>s.Id);}public static void ExportBranches(IEnumerable<ExtremeBranch> rows,string path){ComponentCsv.Export(rows,path,BranchHeader,b=>b.Validate(),b=>b.CircuitId);}
// Pivoted complex Gauss-Jordan; inverse checked against the original admittance matrix.
static Complex[,] Inverse(Complex[,] input){int n=input.GetLength(0);var m=(Complex[,])input.Clone();var inv=new Complex[n,n];double scale=0;for(int i=0;i<n;i++){inv[i,i]=1;for(int j=0;j<n;j++)scale=Math.Max(scale,m[i,j].Magnitude);}Need(scale>0,"Rede sem fonte/impedância.");for(int col=0;col<n;col++){int pivot=col;for(int row=col+1;row<n;row++)if(m[row,col].Magnitude>m[pivot,col].Magnitude)pivot=row;Need(m[pivot,col].Magnitude>scale*1e-12,"Rede flutuante ou numericamente mal condicionada.");for(int j=0;j<n;j++){var tmp=m[col,j];m[col,j]=m[pivot,j];m[pivot,j]=tmp;tmp=inv[col,j];inv[col,j]=inv[pivot,j];inv[pivot,j]=tmp;}var d=m[col,col];for(int j=0;j<n;j++){m[col,j]/=d;inv[col,j]/=d;}for(int i=0;i<n;i++)if(i!=col){var f=m[i,col];for(int j=0;j<n;j++){m[i,j]-=f*m[col,j];inv[i,j]-=f*inv[col,j];}}}double residual=0;for(int i=0;i<n;i++)for(int j=0;j<n;j++){Complex sum=0;for(int k=0;k<n;k++)sum+=input[i,k]*inv[k,j];residual=Math.Max(residual,(sum-(i==j?Complex.One:Complex.Zero)).Magnitude);}Need(!Double.IsNaN(residual)&&residual<1e-7,"Resíduo da matriz de sequência excessivo.");return inv;}
static Complex[] Phases(Complex positive,Complex negative){var a=Complex.FromPolarCoordinates(1,2*Math.PI/3);return new[]{positive+negative,a*a*positive+a*negative,a*positive+a*a*negative};}
static List<ExtremeFaultPoint> Solve(Project p,ExtremeCase config,string scenario){Need(config.Sources.All(x=>!String.Equals(x.Id,"TOTAL",StringComparison.OrdinalIgnoreCase)),"ID de fonte TOTAL é reservado à soma.");Need(Trace(config.Reference)&&Trace(config.DataVersion)&&Trace(config.Conditions),"Cenário sem rastreabilidade: "+scenario);var circuits=p.Boards.SelectMany(b=>b.Circuits).Where(c=>c.Phases==PhaseMode.Trifasico).ToList();Need(circuits.Count>0,"Nenhum circuito trifásico no escopo.");Need(config.Branches.Count==circuits.Count&&config.Branches.All(x=>circuits.Any(c=>c.Id==x.CircuitId)),"Tabela deve cobrir exatamente os circuitos trifásicos: "+scenario);Need(config.Sources.Count>0&&config.Sources.All(s=>s.Active.HasValue),"Informe estado de todas as fontes: "+scenario);var nodes=new Dictionary<string,int>();foreach(var board in p.Boards)nodes.Add("B:"+board.Id,nodes.Count);var ends=new Dictionary<string,int>();foreach(var c in circuits)ends[c.Id]=c.ChildBoardId!=""?nodes["B:"+c.ChildBoardId]:nodes.Count;foreach(var c in circuits)if(c.ChildBoardId==""){ends[c.Id]=nodes.Count;nodes.Add("C:"+c.Id,nodes.Count);}int count=nodes.Count;Need(count<=120,"Limite do solucionador:120 nós.");var y1=new Complex[count,count];var y2=new Complex[count,count];foreach(var item in config.Branches){var c=circuits.First(x=>x.Id==item.CircuitId);Need(item.CircuitContext==Context(p,c),"Ramo alterado após estudo: "+c.Id);Need(item.ConductorTemperatureC.HasValue&&Trace(item.Reference)&&Trace(item.DataVersion)&&Trace(item.Conditions),"Temperatura/rastreabilidade do ramo incompleta: "+c.Id);int from=nodes["B:"+p.Boards.First(b=>b.Circuits.Contains(c)).Id],to=ends[c.Id];var z1=Z(item.R1Ohm,item.X1Ohm,c.Id+" Z1");var z2=Z(item.R2Ohm,item.X2Ohm,c.Id+" Z2");foreach(var entry in new[]{Tuple.Create(y1,z1),Tuple.Create(y2,z2)}){var y=1/entry.Item2;entry.Item1[from,from]+=y;entry.Item1[to,to]+=y;entry.Item1[from,to]-=y;entry.Item1[to,from]-=y;}}
var sources=config.Sources.Where(s=>s.Active==true).ToList();Need(sources.Count>0,"Nenhuma fonte ativa: "+scenario);foreach(var s in config.Sources){Need(nodes.ContainsKey("B:"+s.BoardId)&&s.Kind!=ExtremeSourceKind.Unknown&&Trace(s.Id)&&Trace(s.Reference)&&Trace(s.DataVersion)&&Trace(s.Conditions),"Identidade/tipo/rastreabilidade de fonte incompletos: "+s.Id);if(s.Active!=true)continue;int i=nodes["B:"+s.BoardId];y1[i,i]+=1/Z(s.R1Ohm,s.X1Ohm,s.Id+" Z1");y2[i,i]+=1/Z(s.R2Ohm,s.X2Ohm,s.Id+" Z2");}var zbus1=Inverse(y1);var zbus2=Inverse(y2);double emf=p.FaultExtremes.LineVoltageV/Math.Sqrt(3)*config.VoltageFactor;var result=new List<ExtremeFaultPoint>();foreach(var c in circuits)foreach(var location in new[]{"Origem","Fim"}){int k=location=="Fim"?ends[c.Id]:nodes["B:"+p.Boards.First(b=>b.Circuits.Contains(c)).Id];foreach(var fault in new[]{"3F","LL L2-L3"}){var i1=emf/(fault=="3F"?zbus1[k,k]:zbus1[k,k]+zbus2[k,k]);var i2=fault=="3F"?Complex.Zero:-i1;var ph=Phases(i1,i2);var point=new ExtremeFaultPoint{CircuitId=c.Id,Location=location,Fault=fault,Scenario=scenario,CurrentA=ph.Max(v=>v.Magnitude),FaultCurrent=ph,Z1Thevenin=zbus1[k,k],Z2Thevenin=zbus2[k,k]};var sum=new Complex[3];foreach(var s in sources){int j=nodes["B:"+s.BoardId];var v1=emf-zbus1[j,k]*i1;var v2=-zbus2[j,k]*i2;var sourceI1=(emf-v1)/Z(s.R1Ohm,s.X1Ohm,s.Id);var sourceI2=-v2/Z(s.R2Ohm,s.X2Ohm,s.Id);var currents=Phases(sourceI1,sourceI2);point.Contributions.Add(new ExtremeContribution{SourceId=s.Id,Current=currents});for(int phase=0;phase<3;phase++)sum[phase]+=currents[phase];}point.ResidualA=Enumerable.Range(0,3).Max(i=>(sum[i]-ph[i]).Magnitude);Need(!Double.IsNaN(point.CurrentA)&&!Double.IsInfinity(point.CurrentA)&&point.ResidualA<=Math.Max(1e-6,point.CurrentA*1e-8),"Falha no balanço das contribuições.");result.Add(point);}}return result;}
public static FaultExtremeResult Run(Project p){p.Validate();var result=new FaultExtremeResult();try{var profile=p.FaultExtremes;Need(profile!=null,"Perfil de extremos ausente.");Need(profile.LineVoltageV==p.Source.LineVoltage&&profile.FrequencyHz==p.Frequency&&p.Boards.All(b=>b.Voltage==profile.LineVoltageV),"Tensão/frequência ou transformação intermediária incompatíveis.");Need(Trace(profile.BoundsReference)&&Trace(profile.Coverage),"Declare cobertura/documento dos limites.");var lo=profile.Minimum;var hi=profile.Maximum;Need(lo.VoltageFactor<=hi.VoltageFactor,"Fatores mínimo/máximo invertidos.");Need(lo.Sources.Count==hi.Sources.Count&&lo.Sources.All(s=>hi.Sources.Any(t=>s.Id==t.Id&&s.BoardId==t.BoardId&&s.Kind==t.Kind)),"Identidades/localizações das fontes devem corresponder nos dois cenários.");var minimum=Solve(p,lo,"Mínimo declarado");var maximum=Solve(p,hi,"Máximo declarado");for(int i=0;i<minimum.Count;i++)Need(minimum[i].CurrentA<=maximum[i].CurrentA*(1+1e-9),"Cenários não delimitam mínimo/máximo no ponto "+minimum[i].CircuitId+" "+minimum[i].Location+" "+minimum[i].Fault);result.Points.AddRange(minimum);result.Points.AddRange(maximum);result.Accepted=true;result.Status="Extremos iniciais dos cenários declarados calculados";result.Detail="Sequências positiva/negativa; impedâncias corrigidas fornecidas por cenário; fontes internas simétricas em fase, sem carga pré-falta. Não é IEC60909 integral nem corrente sustentada de máquina. Cobertura: "+profile.Coverage+"; documento "+profile.BoundsReference+". Pontos monofásicos fora do escopo.";return result;}catch(Input ex){result.Status="Dados incompletos/incompatíveis; sem extremos aceitos";result.Detail=ex.Message;return result;}}
static string C(string s,bool text){s=s??"";if(text&&s.TrimStart().Length>0&&"=+-@".Contains(s.TrimStart()[0]))s="'"+s;return "\""+s.Replace("\"","\"\"")+"\"";}
static string Ph(Complex z){return N(z.Real)+" + j("+N(z.Imaginary)+")";}
public static void AppendReport(Project p,FaultExtremeResult result,StringBuilder text,IEnumerable<string> selected){if(result==null)return;text.AppendLine("\r\nEXTREMOS INICIAIS3F/LL — "+EngineId);text.AppendLine(result.Status+". "+result.Detail);if(!result.Accepted)return;var ids=selected==null?null:new HashSet<string>(selected);foreach(var config in new[]{p.FaultExtremes.Minimum,p.FaultExtremes.Maximum}){text.AppendLine("Cenário: "+config.Reference+"; versão "+config.DataVersion+"; c="+config.VoltageFactor+"; "+config.Conditions);foreach(var source in config.Sources)text.AppendLine("Fonte global "+source.Id+" @"+source.BoardId+"; tipo "+source.Kind+"; ativa="+source.Active+"; Z1="+source.R1Ohm+" +j"+source.X1Ohm+" Ω; Z2="+source.R2Ohm+" +j"+source.X2Ohm+" Ω; "+source.Reference+" / "+source.DataVersion+" / "+source.Conditions);foreach(var branch in config.Branches){if(ids!=null&&!ids.Contains(branch.CircuitId))continue;text.AppendLine("Ramo selecionado "+branch.CircuitId+"; T="+branch.ConductorTemperatureC+" °C; Z1="+branch.R1Ohm+" +j"+branch.X1Ohm+" Ω; Z2="+branch.R2Ohm+" +j"+branch.X2Ohm+" Ω; "+branch.Reference+" / "+branch.DataVersion+" / "+branch.Conditions);}}
foreach(var point in result.Points){if(ids!=null&&!ids.Contains(point.CircuitId))continue;text.AppendLine(point.CircuitId+" — "+point.Scenario+" / "+point.Location+" / "+point.Fault+": Ik inicial máx fase="+N(point.CurrentA)+" A; Z1th="+Ph(point.Z1Thevenin)+" Ω; Z2th="+Ph(point.Z2Thevenin)+" Ω; resíduo soma fontes="+N(point.ResidualA)+" A.");foreach(var source in point.Contributions)text.AppendLine("  "+source.SourceId+": IA/IB/IC="+String.Join(" / ",source.Current.Select(Ph))+" A (fasores, não módulos somados).");}text.AppendLine("Totais nominais legados e proteções anteriores permanecem separados deste estudo. Estes dois cenários não provam todos os estados possíveis ou tempo sustentado. Sem fatores normativos/OEM inferidos; fonte de corrente limitada não é admitida como Thévenin.");}
public static void Export(Project p,string path){var result=Run(p);if(!result.Accepted)throw new InvalidDataException("Sem extremos aceitos; arquivo anterior preservado. "+result.Detail);var w=new StringBuilder("Scenario;Circuit;Location;Fault;IkInitialMaxPhaseA;Source;IAReA;IAImA;IBReA;IBImA;ICReA;ICImA;ResidualA;Engine;BoundsReference;Coverage;CaseReference;CaseVersion;CaseConditions;SourceReference\r\n");foreach(var point in result.Points){var config=point.Scenario.StartsWith("Mínimo",StringComparison.Ordinal)?p.FaultExtremes.Minimum:p.FaultExtremes.Maximum;var contributions=new List<ExtremeContribution>{new ExtremeContribution{SourceId="TOTAL",Current=point.FaultCurrent}};contributions.AddRange(point.Contributions);foreach(var row in contributions){var values=new List<string>{C(point.Scenario,true),C(point.CircuitId,true),C(point.Location,true),C(point.Fault,true),C(N(point.CurrentA),false),C(row.SourceId,true)};foreach(var i in row.Current){values.Add(C(N(i.Real),false));values.Add(C(N(i.Imaginary),false));}values.AddRange(new[]{C(N(point.ResidualA),false),C(EngineId,true),C(p.FaultExtremes.BoundsReference,true),C(p.FaultExtremes.Coverage,true),C(config.Reference,true),C(config.DataVersion,true),C(config.Conditions,true),C(row.SourceId=="TOTAL"?"Soma fasorial":config.Sources.First(x=>x.Id==row.SourceId).Reference,true)});w.AppendLine(String.Join(";",values));}}if(Encoding.UTF8.GetByteCount(w.ToString())>32*1024*1024)throw new InvalidDataException("CSV excede32MiB.");string full=Path.GetFullPath(path),temp=full+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temp,w.ToString(),new UTF8Encoding(true));if(File.Exists(full))File.Replace(temp,full,full+".bak");else File.Move(temp,full);}finally{if(File.Exists(temp))File.Delete(temp);}}

}
public sealed partial class Project{[DataMember,Browsable(false)]public FaultExtremeProfile FaultExtremes{get;set;}}
